(175, '_options_all_feedbacks_0_designation', 'field_644b73b5b95d2', 'no'),
(176, 'options_all_feedbacks_1_feedback_texts', 'Ramdhanu-The colour of hope is truly sending life and love to those in need. It says that selfless service for the cause of humanity is as important as worshipping God and Ramdhanu is proving it to be true.', 'no'),
