(1489, 181, 'banner_title', 'Ramdhanu'),
(1490, 181, '_banner_title', 'field_644b754c3b9c4'),
(1491, 181, 'banner_sub_title', 'Bringing Hope, Building Futures'),
(1492, 181, '_banner_sub_title', 'field_644b75743b9c5'),
(1493, 181, 'banner_texts', 'Fighting Poverty and Providing Opportunities for Underprivileged Children'),
