(1868, 187, '_banner_title', 'field_644b754c3b9c4'),
(1869, 187, 'banner_sub_title', 'Bringing Hope, Building Futures'),
(1870, 187, '_banner_sub_title', 'field_644b75743b9c5'),
(1871, 187, 'banner_texts', 'Fighting Poverty and Providing Opportunities for Underprivileged Children'),
