(1954, 187, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(1955, 187, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(1956, 187, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
