(2119, 188, 'mission_title', 'Our Mission, Vision and Goals'),
(2120, 188, '_mission_title', 'field_645213e4feee1'),
(2121, 188, 'mission_section_background', '186'),
(2122, 188, '_mission_section_background', 'field_645213f4feee2'),
(2123, 189, 'banner_title', 'Ramdhanu'),
(2124, 189, '_banner_title', 'field_644b754c3b9c4'),
(2125, 189, 'banner_sub_title', 'Bringing Hope, Building Futures'),
(2126, 189, '_banner_sub_title', 'field_644b75743b9c5'),
(2127, 189, 'banner_texts', 'Fighting Poverty and Providing Opportunities for Underprivileged Children'),
(2128, 189, '_banner_texts', 'field_644b75883b9c6'),
(2129, 189, 'youtube_url', 'https://www.youtube.com/watch?v=uemObN8_dcw'),
(2130, 189, '_youtube_url', 'field_644b75993b9c7'),
(2131, 189, 'about_title', 'Ramdhanu - The Colour of Hope for Marginalised Children'),
(2132, 189, '_about_title', 'field_644bc06c879bc'),
(2133, 189, 'about_texts', '<p class=\"main-color\">Enabling Children to Live with Dignity and Opportunity</p>\r\nRamdhanu is a society committed to providing equal rights, education, and opportunities to all children, especially those who are marginalised and living on the streets. Our vision is to empower these children through education, nutrition, healthcare, and cultural activities, so they can lead fulfilling lives and contribute positively to society. With the help of professional educators, we enroll street children in schools and support them with educational materials. We provide nutritious food to address their dietary needs, and conduct medical camps to address their health and hygiene issues. We also organize cultural events on notable days to encourage their active participation. Our goal is to create a space where all children have access to the resources they need to thrive.'),
(2134, 189, '_about_texts', 'field_644bc086879bd'),
(2135, 189, 'cause_title', 'Learn About the Issues We Care Deeply About and Our Efforts to Make a Difference'),
(2136, 189, '_cause_title', 'field_644bc3a4879bf'),
(2137, 189, 'cause_subtitle', 'Discover the causes that inspire and motivate us to create change. From empowering underprivileged children to protecting the environment, we are committed to driving progress in areas that matter. Explore our causes and join us in making a meaningful impact on the world.'),
(2138, 189, '_cause_subtitle', 'field_644bc3b4879c0'),
(2139, 189, 'all_causes', '4'),
(2140, 189, '_all_causes', 'field_644bc3c3879c1'),
(2141, 189, 'newsletter_title', 'Brighter Horizons - A Newsletter of Ramdhanu Society'),
(2142, 189, '_newsletter_title', 'field_644bca19defeb'),
(2143, 189, 'newsletter_subtitle', 'Bringing You the Latest Updates on Our Efforts to Build a Better Future for All Children'),
(2144, 189, '_newsletter_subtitle', 'field_644bca36defec'),
(2145, 189, 'impact_title', 'From Darkness and Pain to Brighter Futures - Our Journey of Empowerment'),
(2146, 189, '_impact_title', 'field_644bca5ccb4e9'),
(2147, 189, 'impact_subtitle', 'Experience the meaningful impact that Ramdhanu is creating in the lives of underprivileged children. From providing education to ensuring basic necessities, we are making a positive difference one child at a time. See our key achievements and join us in making the world a better place.'),
(2148, 189, '_impact_subtitle', 'field_644bca6ccb4ea'),
(2149, 189, 'impact_blocks', '4'),
(2150, 189, '_impact_blocks', 'field_644bcb1bfa37a'),
(2151, 189, 'counter_section_title', 'Bringing Education, Nutrition and Hope to Underprivileged Children'),
(2152, 189, '_counter_section_title', 'field_644bcbc35a63e'),
(2153, 189, 'counter_section_subtitle', 'Through our initiatives, we have enrolled children in school, supplied educational materials, provided nutritious meals, and organized workshops, helping them to achieve their full potential and break the cycle of poverty.'),
(2154, 189, '_counter_section_subtitle', 'field_644bceb65a63f'),
(2155, 189, 'counters', '4'),
(2156, 189, '_counters', 'field_644bcf555a640'),
(2157, 189, 'counter_section_image', ''),
(2158, 189, '_counter_section_image', 'field_644d468c49b85'),
(2159, 189, 'mission_contents_our_mission', 'At our organization, our mission is to empower underprivileged children with the tools they need to succeed. We believe that every child has the right to access education, nutrition, and healthcare, and we are committed to providing these resources to those who need them most. By working closely with the community, we aim to create sustainable change and break the cycle of poverty. We believe that by investing in the future of these children, we are investing in the future of our world.'),
(2160, 189, '_mission_contents_our_mission', 'field_644bd718f8dfa'),
(2161, 189, 'mission_contents_our_vision', 'Our vision is a world where every child has equal opportunities to thrive and succeed, regardless of their circumstances. We envision a future where poverty and inequality no longer limit a child\'s potential and access to education, nutrition, and healthcare are universal rights. We believe that every child has the potential to make a positive impact on the world, and by empowering them with the tools they need to succeed, we can create a brighter future for all. We are committed to working towards this vision, one child at a time, and we invite others to join us on this journey.'),
(2162, 189, '_mission_contents_our_vision', 'field_644bd746f8dfb'),
(2163, 189, 'mission_contents_our_goal', '<ul>\r\n 	<li><span style=\"color: #ffffff;\">Increase access to education: We strive to ensure that every child has access to quality education by providing educational materials, scholarships, and mentorship.</span></li>\r\n 	<li><span style=\"color: #ffffff;\">Improve health outcomes: We work to improve the health and well-being of underprivileged children by providing nutritious meals, access to healthcare, and hygiene education.</span></li>\r\n 	<li><span style=\"color: #ffffff;\">Empower the community: We aim to create a sustainable impact by empowering the community through our programs, promoting local leadership, and fostering community involvement.</span></li>\r\n 	<li><span style=\"color: #ffffff;\">Expand our reach: We aim to expand our programs to reach more underprivileged children and communities in need, and to work towards creating a better future for all.</span></li>\r\n</ul>'),
(2164, 189, '_mission_contents_our_goal', 'field_644bd751f8dfc'),
(2165, 189, 'mission_contents', ''),
(2166, 189, '_mission_contents', 'field_644bd6f7f8df9'),
