(2337, 190, 'impact_blocks_0_impact_title', 'Education for All'),
(2338, 190, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(2339, 190, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(2340, 190, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(2341, 190, 'impact_blocks_1_impact_icon', ''),
(2342, 190, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(2343, 190, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(2344, 190, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(2345, 190, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(2346, 190, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(2347, 190, 'impact_blocks_2_impact_icon', ''),
