(2350, 190, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(2351, 190, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(2352, 190, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
