(2597, 194, 'impact_blocks_0_impact_title', 'Education for All'),
(2598, 194, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(2599, 194, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(2600, 194, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(2601, 194, 'impact_blocks_1_impact_icon', ''),
(2602, 194, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(2603, 194, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(2604, 194, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(2605, 194, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(2606, 194, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(2607, 194, 'impact_blocks_2_impact_icon', ''),
(2608, 194, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(2609, 194, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(2610, 194, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(2611, 194, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(2612, 194, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(2613, 194, 'impact_blocks_3_impact_icon', ''),
