(2989, 202, 'impact_blocks_0_impact_icon', '197'),
(2990, 202, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(2991, 202, 'impact_blocks_0_impact_title', 'Education for All'),
(2992, 202, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(2993, 202, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(2994, 202, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(2995, 202, 'impact_blocks_1_impact_icon', '196'),
(2996, 202, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(2997, 202, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(2998, 202, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(2999, 202, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(3000, 202, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(3001, 202, 'impact_blocks_2_impact_icon', '195'),
(3002, 202, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(3003, 202, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(3004, 202, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(3005, 202, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(3006, 202, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(3007, 202, 'impact_blocks_3_impact_icon', '198'),
