(3010, 202, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(3011, 202, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(3012, 202, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
