(4254, 292, '_all_causes_0_cause_tag', 'field_644bc3fd879c3'),
(4255, 292, 'all_causes_0_cause_title', 'Color Of Hope'),
(4256, 292, '_all_causes_0_cause_title', 'field_644bc417879c4'),
(4257, 292, 'all_causes_0_cause_texts', 'Bringing hope and education to underprivileged children through art, literacy, and holistic support.'),
(4258, 292, '_all_causes_0_cause_texts', 'field_644bc424879c5'),
