(4265, 292, 'all_causes_1_cause_title', 'Ray Of Hope'),
(4266, 292, '_all_causes_1_cause_title', 'field_644bc417879c4'),
(4267, 292, 'all_causes_1_cause_texts', 'Providing care, education, and opportunities for blind children to live a fulfilling life.'),
(4268, 292, '_all_causes_1_cause_texts', 'field_644bc424879c5'),
(4269, 292, 'all_causes_1_button_url', ''),
(4270, 292, '_all_causes_1_button_url', 'field_644bc439879c6'),
(4271, 292, 'all_causes_2_cause_image', '200'),
(4272, 292, '_all_causes_2_cause_image', 'field_644bc3d2879c2'),
(4273, 292, 'all_causes_2_cause_tag', '#Outreach'),
(4274, 292, '_all_causes_2_cause_tag', 'field_644bc3fd879c3'),
(4275, 292, 'all_causes_2_cause_title', 'Beyond Boundaries'),
(4276, 292, '_all_causes_2_cause_title', 'field_644bc417879c4'),
(4277, 292, 'all_causes_2_cause_texts', 'Breaking barriers and reaching remote areas to educate and nourish underprivileged children.'),
(4278, 292, '_all_causes_2_cause_texts', 'field_644bc424879c5'),
(4279, 292, 'all_causes_2_button_url', ''),
(4280, 292, '_all_causes_2_button_url', 'field_644bc439879c6'),
(4281, 292, 'all_causes_3_cause_image', '200'),
(4282, 292, '_all_causes_3_cause_image', 'field_644bc3d2879c2'),
(4283, 292, 'all_causes_3_cause_tag', '#Compassion'),
(4284, 292, '_all_causes_3_cause_tag', 'field_644bc3fd879c3'),
(4285, 292, 'all_causes_3_cause_title', 'On The Street, For The Street'),
(4286, 292, '_all_causes_3_cause_title', 'field_644bc417879c4'),
(4287, 292, 'all_causes_3_cause_texts', 'Serving Homeless and Underprivileged Communities with Compassion.'),
(4288, 292, '_all_causes_3_cause_texts', 'field_644bc424879c5'),
(4289, 292, 'all_causes_3_button_url', ''),
(4290, 292, '_all_causes_3_button_url', 'field_644bc439879c6'),
(4291, 292, 'impact_blocks_0_impact_icon', '197'),
(4292, 292, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(4293, 292, 'impact_blocks_0_impact_title', 'Education for All'),
(4294, 292, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(4295, 292, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(4296, 292, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(4297, 292, 'impact_blocks_1_impact_icon', '196'),
(4298, 292, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(4299, 292, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(4300, 292, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(4301, 292, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(4302, 292, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(4303, 292, 'impact_blocks_2_impact_icon', '195'),
(4304, 292, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(4305, 292, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(4306, 292, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(4307, 292, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(4308, 292, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(4309, 292, 'impact_blocks_3_impact_icon', '198'),
(4310, 292, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
