(4418, 295, '_all_causes_3_cause_title', 'field_644bc417879c4'),
(4419, 295, 'all_causes_3_cause_texts', 'Serving Homeless and Underprivileged Communities with Compassion.'),
(4420, 295, '_all_causes_3_cause_texts', 'field_644bc424879c5'),
(4421, 295, 'all_causes_3_button_url', ''),
(4422, 295, '_all_causes_3_button_url', 'field_644bc439879c6'),
(4423, 295, 'impact_blocks_0_impact_icon', '197'),
(4424, 295, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(4425, 295, 'impact_blocks_0_impact_title', 'Education for All'),
(4426, 295, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(4427, 295, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(4428, 295, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(4429, 295, 'impact_blocks_1_impact_icon', '196'),
(4430, 295, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(4431, 295, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(4432, 295, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(4433, 295, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(4434, 295, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(4435, 295, 'impact_blocks_2_impact_icon', '195'),
(4436, 295, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(4437, 295, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(4438, 295, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(4439, 295, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(4440, 295, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
