(4556, 297, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(4557, 297, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(4558, 297, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(4559, 297, 'impact_blocks_1_impact_icon', '196'),
