(4561, 297, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(4562, 297, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(4563, 297, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(4564, 297, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(4565, 297, 'impact_blocks_2_impact_icon', '195'),
