(4808, 301, '_all_causes_3_cause_title', 'field_644bc417879c4'),
(4809, 301, 'all_causes_3_cause_texts', 'Serving Homeless and Underprivileged Communities with Compassion.'),
(4810, 301, '_all_causes_3_cause_texts', 'field_644bc424879c5'),
(4811, 301, 'all_causes_3_button_url', ''),
(4812, 301, '_all_causes_3_button_url', 'field_644bc439879c6'),
(4813, 301, 'impact_blocks_0_impact_icon', '197'),
(4814, 301, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(4815, 301, 'impact_blocks_0_impact_title', 'Education for All'),
(4816, 301, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(4817, 301, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(4818, 301, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(4819, 301, 'impact_blocks_1_impact_icon', '196'),
(4820, 301, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(4821, 301, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(4822, 301, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(4823, 301, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(4824, 301, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(4825, 301, 'impact_blocks_2_impact_icon', '195'),
(4826, 301, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(4827, 301, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(4828, 301, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(4829, 301, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(4830, 301, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(4831, 301, 'impact_blocks_3_impact_icon', '198'),
(4832, 301, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(4833, 301, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(4834, 301, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(4835, 301, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(4836, 301, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
