(7274, 452, 'section_2_title', 'Our Instructors'),
(7275, 452, '_section_2_title', 'field_644be7c178ed3'),
(7276, 452, 'section_2_title_copy', 'At Color of Hope, we have had the opportunity to organize multiple one-day workshops with various instructors, but we are fortunate to have three dedicated teachers who take regular classes for our children. Sneha and Namita, two compassionate undergraduate students, conduct classes for three girls who are preparing for their board exams, even though they have to do so on the footpath due to lack of shelter. Meanwhile, Sumana Ma\'am, our music instructor, takes weekly classes and is passionate about teaching our children. We are grateful for their commitment and contribution to the education and growth of our children.'),
(7277, 452, '_section_2_title_copy', 'field_644be7d578ed4'),
(7278, 452, 'section_2_content', ''),
(7279, 452, '_section_2_content', 'field_644be74878ece'),
(7280, 452, 'newsletter_title', 'Brighter Horizons - A Newsletter Of Ramdhanu Society'),
(7281, 452, '_newsletter_title', 'field_644be817597e2'),
(7282, 452, 'newsletter_subtitle', 'Bringing You The Latest Updates On Our Efforts To Build A Better Future For All Children'),
(7283, 452, '_newsletter_subtitle', 'field_644be834597e3'),
(7284, 452, 'section_4_contents', '2'),
(7285, 452, '_section_4_contents', 'field_644be85327417'),
(7286, 452, 'section_4_contents_0_section4_image', '446'),
