(7573, 464, 'impact_blocks_0_impact_icon', '197'),
(7574, 464, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(7575, 464, 'impact_blocks_0_impact_title', 'Education for All'),
(7576, 464, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(7577, 464, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(7578, 464, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(7579, 464, 'impact_blocks_1_impact_icon', '196'),
(7580, 464, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(7581, 464, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(7582, 464, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(7583, 464, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(7584, 464, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(7585, 464, 'impact_blocks_2_impact_icon', '195'),
(7586, 464, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(7587, 464, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(7588, 464, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(7589, 464, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(7590, 464, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(7591, 464, 'impact_blocks_3_impact_icon', '198'),
(7592, 464, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(7593, 464, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(7594, 464, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(7595, 464, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(7596, 464, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
