(7961, 469, 'impact_blocks_0_impact_icon', '197'),
(7962, 469, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(7963, 469, 'impact_blocks_0_impact_title', 'Education for All'),
(7964, 469, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(7965, 469, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(7966, 469, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(7967, 469, 'impact_blocks_1_impact_icon', '196'),
(7968, 469, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(7969, 469, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(7970, 469, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(7971, 469, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(7972, 469, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(7973, 469, 'impact_blocks_2_impact_icon', '195'),
(7974, 469, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(7975, 469, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(7976, 469, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(7977, 469, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(7978, 469, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(7979, 469, 'impact_blocks_3_impact_icon', '198'),
(7980, 469, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(7981, 469, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(7982, 469, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(7983, 469, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(7984, 469, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
