(11145, 747, '_youtube_video', 'field_644be72f78ecc'),
(11146, 747, 'section_2_title', 'Activities'),
(11147, 747, '_section_2_title', 'field_644be7c178ed3'),
(11148, 747, 'section_2_title_copy', ''),
(11149, 747, '_section_2_title_copy', 'field_644be7d578ed4'),
(11150, 747, 'section_2_content', '4'),
(11151, 747, '_section_2_content', 'field_644be74878ece'),
(11152, 747, 'newsletter_title', 'Brighter Horizons - A Newsletter Of Ramdhanu Society'),
(11153, 747, '_newsletter_title', 'field_644be817597e2'),
(11154, 747, 'newsletter_subtitle', 'Bringing You The Latest Updates On Our Efforts To Build A Better Future For All Children'),
(11155, 747, '_newsletter_subtitle', 'field_644be834597e3'),
(11156, 747, 'section_4_contents', '1'),
(11157, 747, '_section_4_contents', 'field_644be85327417'),
(11158, 747, 'section_2_content_0_section_2_image', ''),
(11159, 747, '_section_2_content_0_section_2_image', 'field_644be75478ecf'),
(11160, 747, 'section_2_content_0_section_2_content_title', 'Art Workshops'),
(11161, 747, '_section_2_content_0_section_2_content_title', 'field_644be76078ed0'),
(11162, 747, 'section_2_content_0_section_2_content_texts', 'Regular art workshops are conducted where children learn various forms of art, from painting and sketching to crafts and digital art. These sessions are led by professional artists and volunteers passionate about making a difference.'),
(11163, 747, '_section_2_content_0_section_2_content_texts', 'field_644be78d78ed1'),
(11164, 747, 'section_2_content_0_section_2_content_tag', ''),
(11165, 747, '_section_2_content_0_section_2_content_tag', 'field_644be7a878ed2'),
(11166, 747, 'section_2_content_1_section_2_image', ''),
(11167, 747, '_section_2_content_1_section_2_image', 'field_644be75478ecf'),
(11168, 747, 'section_2_content_1_section_2_content_title', 'Art Exhibitions'),
(11169, 747, '_section_2_content_1_section_2_content_title', 'field_644be76078ed0'),
(11170, 747, 'section_2_content_1_section_2_content_texts', 'The children\'s artworks are showcased in exhibitions, giving them a platform to display their talent. These exhibitions are also a means to raise awareness about the children\'s lives and aspirations, and they often include fundraising components to support the project.'),
(11171, 747, '_section_2_content_1_section_2_content_texts', 'field_644be78d78ed1'),
(11172, 747, 'section_2_content_1_section_2_content_tag', ''),
(11173, 747, '_section_2_content_1_section_2_content_tag', 'field_644be7a878ed2'),
(11174, 747, 'section_2_content_2_section_2_image', ''),
(11175, 747, '_section_2_content_2_section_2_image', 'field_644be75478ecf'),
(11176, 747, 'section_2_content_2_section_2_content_title', 'Public Art Projects'),
(11177, 747, '_section_2_content_2_section_2_content_title', 'field_644be76078ed0'),
(11178, 747, 'section_2_content_2_section_2_content_texts', 'Collaborative murals and community art projects bring color and life to public spaces while fostering teamwork and a sense of pride among the children. These projects often address social themes and encourage children to think critically about their surroundings.'),
(11179, 747, '_section_2_content_2_section_2_content_texts', 'field_644be78d78ed1'),
(11180, 747, 'section_2_content_2_section_2_content_tag', ''),
(11181, 747, '_section_2_content_2_section_2_content_tag', 'field_644be7a878ed2'),
(11182, 747, 'section_2_content_3_section_2_image', ''),
(11183, 747, '_section_2_content_3_section_2_image', 'field_644be75478ecf'),
(11184, 747, 'section_2_content_3_section_2_content_title', 'Art Therapy'),
(11185, 747, '_section_2_content_3_section_2_content_title', 'field_644be76078ed0'),
(11186, 747, 'section_2_content_3_section_2_content_texts', 'For children who have experienced trauma, art therapy sessions provide a safe and supportive environment to express their emotions and begin healing. These sessions are conducted by trained therapists who specialize in working with children.'),
(11187, 747, '_section_2_content_3_section_2_content_texts', 'field_644be78d78ed1'),
(11188, 747, 'section_2_content_3_section_2_content_tag', ''),
(11189, 747, '_section_2_content_3_section_2_content_tag', 'field_644be7a878ed2'),
(11190, 747, 'section_4_contents_0_section4_image', ''),
(11191, 747, '_section_4_contents_0_section4_image', 'field_644be8882741a'),
(11192, 747, 'section_4_contents_0_alignment', 'left'),
(11193, 747, '_section_4_contents_0_alignment', 'field_644be8972741b'),
(11194, 747, 'section_4_contents_0_section4_title', '<h3>Impact</h3>\r\n<p class=\"main-color\">Hopes &amp; Hues has significantly impacted the lives of many children, providing them with a constructive outlet for their creativity and emotions. The project has not only enhanced their artistic skills but also boosted their self-esteem, improved their academic performance, and fostered a sense of hope and possibility.</p>'),
(11195, 747, '_section_4_contents_0_section4_title', 'field_644be8cf2741d'),
(11196, 744, '_yoast_wpseo_content_score', '90'),
