(13299, 891, 'section_2_title', 'Our Purpose'),
(13300, 891, '_section_2_title', 'field_644be7c178ed3'),
(13301, 891, 'section_2_title_copy', 'To build confidence and self-reliance through creative skills. To provide an alternative source of income for families living in poverty. To preserve traditional crafts while adapting them for sustainable livelihood. To reinvest profits into education, healthcare, and nutrition of children under our care.'),
