(13847, 843, '_all_causes_2_button_url', 'field_644bc439879c6'),
(13848, 843, 'all_causes_3_cause_image', '466'),
(13849, 843, '_all_causes_3_cause_image', 'field_644bc3d2879c2'),
(13850, 843, 'all_causes_3_cause_tag', '#Compassion'),
(13851, 843, '_all_causes_3_cause_tag', 'field_644bc3fd879c3'),
(13852, 843, 'all_causes_3_cause_title', 'On The Street, For The Street'),
(13853, 843, '_all_causes_3_cause_title', 'field_644bc417879c4'),
(13854, 843, 'all_causes_3_cause_texts', 'Serving Homeless and Underprivileged Communities with Compassion.'),
(13855, 843, '_all_causes_3_cause_texts', 'field_644bc424879c5'),
(13856, 843, 'all_causes_3_button_url', 'a:3:{s:5:\"title\";s:29:\"On the Street, For The Street\";s:3:\"url\";s:54:\"http://localhost/ramdhanu-website/on-the-street-for-the-street/\";s:6:\"target\";s:0:\"\";}'),
(13857, 843, '_all_causes_3_button_url', 'field_644bc439879c6'),
(13858, 843, 'impact_blocks_0_impact_icon', '197'),
(13859, 843, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(13860, 843, 'impact_blocks_0_impact_title', 'Education for All'),
(13861, 843, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(13862, 843, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(13863, 843, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(13864, 843, 'impact_blocks_1_impact_icon', '196'),
(13865, 843, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(13866, 843, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(13867, 843, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(13868, 843, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(13869, 843, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(13870, 843, 'impact_blocks_2_impact_icon', '195'),
(13871, 843, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(13872, 843, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(13873, 843, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(13874, 843, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(13875, 843, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(13876, 843, 'impact_blocks_3_impact_icon', '198'),
(13877, 843, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(13878, 843, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(13879, 843, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(13880, 843, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(13881, 843, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
