(14041, 915, '_all_causes_3_cause_tag', 'field_644bc3fd879c3'),
(14042, 915, 'all_causes_3_cause_title', 'On The Street, For The Street'),
(14043, 915, '_all_causes_3_cause_title', 'field_644bc417879c4'),
(14044, 915, 'all_causes_3_cause_texts', 'Serving Homeless and Underprivileged Communities with Compassion.'),
(14045, 915, '_all_causes_3_cause_texts', 'field_644bc424879c5'),
(14046, 915, 'all_causes_3_button_url', 'a:3:{s:5:\"title\";s:29:\"On the Street, For The Street\";s:3:\"url\";s:54:\"http://localhost/ramdhanu-website/on-the-street-for-the-street/\";s:6:\"target\";s:0:\"\";}'),
(14047, 915, '_all_causes_3_button_url', 'field_644bc439879c6'),
(14048, 915, 'impact_blocks_0_impact_icon', '197'),
(14049, 915, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(14050, 915, 'impact_blocks_0_impact_title', 'Education for All'),
(14051, 915, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(14052, 915, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(14053, 915, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(14054, 915, 'impact_blocks_1_impact_icon', '196'),
(14055, 915, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(14056, 915, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(14057, 915, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(14058, 915, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(14059, 915, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(14060, 915, 'impact_blocks_2_impact_icon', '195'),
(14061, 915, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(14062, 915, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(14063, 915, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(14064, 915, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(14065, 915, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(14066, 915, 'impact_blocks_3_impact_icon', '198'),
(14067, 915, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(14068, 915, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(14069, 915, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(14070, 915, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(14071, 915, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
