(14178, 925, 'impact_blocks_0_impact_icon', '197'),
(14179, 925, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(14180, 925, 'impact_blocks_0_impact_title', 'Education for All'),
(14181, 925, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(14182, 925, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(14183, 925, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(14184, 925, 'impact_blocks_1_impact_icon', '196'),
(14185, 925, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(14186, 925, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(14187, 925, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(14188, 925, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(14189, 925, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(14190, 925, 'impact_blocks_2_impact_icon', '195'),
(14191, 925, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(14192, 925, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(14193, 925, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(14194, 925, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(14195, 925, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(14196, 925, 'impact_blocks_3_impact_icon', '198'),
(14197, 925, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(14198, 925, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(14199, 925, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(14200, 925, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(14201, 925, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
