(14321, 926, 'impact_subtitle', 'Experience the meaningful impact that Ramdhanu is creating in the lives of underprivileged children. From providing education to ensuring basic necessities, we are making a positive difference one child at a time. See our key achievements and join us in making the world a better place.'),
(14322, 926, '_impact_subtitle', 'field_644bca6ccb4ea'),
(14323, 926, 'impact_blocks', '4'),
(14324, 926, '_impact_blocks', 'field_644bcb1bfa37a'),
(14325, 926, 'counter_section_title', 'Bringing Education, Nutrition and Hope to Underprivileged Children'),
(14326, 926, '_counter_section_title', 'field_644bcbc35a63e'),
(14327, 926, 'counter_section_subtitle', 'Through our initiatives, we have enrolled children in school, supplied educational materials, provided nutritious meals, and organized workshops, helping them to achieve their full potential and break the cycle of poverty.'),
(14328, 926, '_counter_section_subtitle', 'field_644bceb65a63f'),
