(14613, 932, '_all_causes_2_cause_tag', 'field_644bc3fd879c3'),
(14614, 932, 'all_causes_2_cause_title', 'Hopes and Hues'),
(14615, 932, '_all_causes_2_cause_title', 'field_644bc417879c4'),
(14616, 932, 'all_causes_2_cause_texts', 'It’s a heartfelt movement — where brushes, needles, and threads become tools of liberation.'),
(14617, 932, '_all_causes_2_cause_texts', 'field_644bc424879c5'),
(14618, 932, 'all_causes_2_button_url', 'a:3:{s:5:\"title\";s:16:\"Hopes &amp; Hues\";s:3:\"url\";s:36:\"http://localhost/ramdhanu-website/hopes-hues/\";s:6:\"target\";s:0:\"\";}'),
(14619, 932, '_all_causes_2_button_url', 'field_644bc439879c6'),
(14620, 932, 'impact_blocks_0_impact_icon', '197'),
(14621, 932, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(14622, 932, 'impact_blocks_0_impact_title', 'Education for All'),
(14623, 932, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(14624, 932, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(14625, 932, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(14626, 932, 'impact_blocks_1_impact_icon', '196'),
(14627, 932, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(14628, 932, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(14629, 932, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(14630, 932, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(14631, 932, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(14632, 932, 'impact_blocks_2_impact_icon', '195'),
(14633, 932, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(14634, 932, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(14635, 932, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(14636, 932, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(14637, 932, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(14638, 932, 'impact_blocks_3_impact_icon', '198'),
(14639, 932, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(14640, 932, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(14641, 932, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(14642, 932, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(14643, 932, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
