(14892, 936, '_all_causes_0_cause_tag', 'field_644bc3fd879c3'),
(14893, 936, 'all_causes_0_cause_title', 'Color Of Hope'),
(14894, 936, '_all_causes_0_cause_title', 'field_644bc417879c4'),
(14895, 936, 'all_causes_0_cause_texts', 'Bringing hope and education to underprivileged children through art, literacy, and holistic support.'),
