(15253, 939, '_all_causes_1_cause_tag', 'field_644bc3fd879c3'),
(15254, 939, 'all_causes_1_cause_title', 'Beyond Boundaries'),
(15255, 939, '_all_causes_1_cause_title', 'field_644bc417879c4'),
(15256, 939, 'all_causes_1_cause_texts', 'Breaking barriers and reaching remote areas to educate and nourish underprivileged children.'),
(15257, 939, '_all_causes_1_cause_texts', 'field_644bc424879c5'),
(15258, 939, 'all_causes_1_button_url', 'a:3:{s:5:\"title\";s:17:\"Beyond Boundaries\";s:3:\"url\";s:43:\"http://localhost/ramdhanu-website/beyond-boundaries/\";s:6:\"target\";s:0:\"\";}'),
(15259, 939, '_all_causes_1_button_url', 'field_644bc439879c6'),
(15260, 939, 'all_causes_2_cause_image', '933'),
(15261, 939, '_all_causes_2_cause_image', 'field_644bc3d2879c2'),
(15262, 939, 'all_causes_2_cause_tag', '#SkillWithDignity'),
(15263, 939, '_all_causes_2_cause_tag', 'field_644bc3fd879c3'),
(15264, 939, 'all_causes_2_cause_title', 'Hopes and Hues'),
(15265, 939, '_all_causes_2_cause_title', 'field_644bc417879c4'),
(15266, 939, 'all_causes_2_cause_texts', 'It’s a heartfelt movement — where brushes, needles, and threads become tools of liberation.'),
(15267, 939, '_all_causes_2_cause_texts', 'field_644bc424879c5'),
(15268, 939, 'all_causes_2_button_url', 'a:3:{s:5:\"title\";s:16:\"Hopes &amp; Hues\";s:3:\"url\";s:36:\"http://localhost/ramdhanu-website/hopes-hues/\";s:6:\"target\";s:0:\"\";}'),
(15269, 939, '_all_causes_2_button_url', 'field_644bc439879c6'),
(15270, 939, 'impact_blocks_0_impact_icon', '197'),
(15271, 939, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(15272, 939, 'impact_blocks_0_impact_title', 'Education for All'),
(15273, 939, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(15274, 939, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(15275, 939, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(15276, 939, 'impact_blocks_1_impact_icon', '196'),
(15277, 939, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(15278, 939, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(15279, 939, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(15280, 939, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(15281, 939, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(15282, 939, 'impact_blocks_2_impact_icon', '195'),
(15283, 939, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(15284, 939, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(15285, 939, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(15286, 939, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(15287, 939, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(15288, 939, 'impact_blocks_3_impact_icon', '198'),
(15289, 939, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(15290, 939, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(15291, 939, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
