(15592, 953, '_all_causes_2_cause_title', 'field_644bc417879c4'),
(15593, 953, 'all_causes_2_cause_texts', 'It’s a heartfelt movement — where brushes, needles, and threads become tools of liberation.'),
(15594, 953, '_all_causes_2_cause_texts', 'field_644bc424879c5'),
(15595, 953, 'all_causes_2_button_url', 'a:3:{s:5:\"title\";s:12:\"Hopes & Hues\";s:3:\"url\";s:36:\"http://localhost/ramdhanu-website/hopes-hues/\";s:6:\"target\";s:0:\"\";}'),
